export function applyRefraction(host,ids,rgb,meta,m){
 const no=()=>({available:false,written:0});const hex=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
 if(!meta||!m||!['OPEN','CLOSED'].includes(meta.state)||!hex(meta.sourceSHA)||!hex(m.sources?.[meta.state]?.sha256)||meta.sourceSHA!==m.sources[meta.state].sha256||typeof meta.revision!=='string'||!meta.revision||typeof m.revision!=='string'||!m.revision||meta.revision!==m.revision||m.allowedPixels!==82746||meta.rest===true||meta.enabled!==true||meta.conflict!==false||!Number.isFinite(meta.timeMs)||!Array.isArray(meta.camera)||meta.camera.length!==4)return no();
 const[cx,cy,w,h]=meta.camera;if(![cx,cy,w,h].every(Number.isInteger)||cx<0||cy<0||w<1||h<1||cx+w>4294||cy+h>2400||host?.length!==w*h*4||ids?.length!==82746||rgb?.length!==48*82746*3)return no();const phase=((Math.floor(meta.timeMs/50)%48)+48)%48;let written=0;for(let i=0;i<ids.length;i++){let id=ids[i],x=id%4294-cx,y=Math.floor(id/4294)-cy;if(x<0||x>=w||y<0||y>=h)continue;let d=(y*w+x)*4,s=(phase*ids.length+i)*3;host[d]=rgb[s];host[d+1]=rgb[s+1];host[d+2]=rgb[s+2];written++;}return{available:true,written,phase};}
